import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        K = int(next(iterator))
        x = []
        for _ in range(N):
            x.append(int(next(iterator)))
    except StopIteration:
        return

    total_distance = 0
    for xi in x:
        dist_a = xi * 2
        dist_b = (K - xi) * 2
        total_distance += min(dist_a, dist_b)

    print(total_distance)

if __name__ == "__main__":
    solve()
